import type { TaskKey } from '../config/models.js';
import { normalizeTr } from '../lib/normalize-tr.js';

/**
 * Turkish texts generated by the backend (task labels, call-checklist questions). The mobile UI strings live
 * in the app's single l10n file; this file is the backend counterpart.
 */

export const TASK_LABELS: Readonly<Record<TaskKey, string>> = {
  'vision.menu_extract': 'Menü fotoğrafı okuma',
  'vision.panel_extract': 'Panel ekran görüntüsü okuma',
  'text.item_enrich': 'Ürün kartı üretme',
  'text.normalize_classify': 'İsim eşleştirme',
  'text.gap_suggest': 'Eksik ürün önerisi',
  'deep.analyze': 'Derin analiz',
  embed: 'Anlamsal arama (embedding)',
  'audio.transcribe': 'Sesli not (konuşmayı yazıya çevirme)',
  'research.web': 'Restoranı internette araştırma',
};

/** "a" · "a ve b" · "a, b ve c" */
export function joinTr(parts: readonly string[]): string {
  if (parts.length <= 1) return parts[0] ?? '';
  return `${parts.slice(0, -1).join(', ')} ve ${parts.at(-1) ?? ''}`;
}

type GapFieldKey = 'description' | 'options' | 'removables';

const FIELD_ACCUSATIVE: Readonly<Record<GapFieldKey, string>> = {
  description: 'açıklamayı',
  options: 'seçenekleri',
  removables: 'çıkarılabilir malzemeleri',
};

/** Natural questions for option groups that recur across a cuisine (keys are group names as used in templates). */
const CUISINE_GROUP_QUESTIONS = new Map(
  Object.entries({
    'Acı Seviyesi': 'Acı seviyesi soruluyor mu?',
    'Ekmek Tercihi': 'Ekmek / lavaş tercihi soruluyor mu?',
    İçecek: 'İçecekli menü seçeneği var mı?',
    Yanında: 'Yanında gelenler seçilebiliyor mu?',
    Sos: 'Sos seçimi var mı?',
    'Pişirme Derecesi': 'Pişirme derecesi soruluyor mu?',
    Şeker: 'Şeker oranı soruluyor mu?',
    Dondurma: 'Yanına dondurma eklenebiliyor mu?',
    'Servis Şekli': 'Servis şekli (porsiyon / dürüm / ekmek arası) seçilebiliyor mu?',
  }).map(([group, question]) => [normalizeTr(group), question] as const),
);

export const GAP_TEXT = {
  missingItem: (name: string) => `${name} var mı?`,
  itemFields: (name: string, absent: readonly GapFieldKey[], unknown: readonly GapFieldKey[]) => {
    const parts: string[] = [];
    if (absent.length > 0) parts.push(`${joinTr(absent.map((f) => FIELD_ACCUSATIVE[f]))} sor`);
    if (unknown.length > 0) parts.push(`${joinTr(unknown.map((f) => FIELD_ACCUSATIVE[f]))} kontrol et`);
    return `${name}: ${parts.join('; ')}`;
  },
  optionsHint: (group: string, options: readonly string[], otherGroups: readonly string[]) =>
    `${group}: ${options.join(' / ')}${otherGroups.length > 0 ? ` · ayrıca ${otherGroups.join(', ')}` : ''}`,
  removablesHint: (items: readonly string[]) => `Çıkarılabilir: ${items.join(', ')}`,
  cuisineGroup: (group: string) => CUISINE_GROUP_QUESTIONS.get(normalizeTr(group)) ?? `${group} seçimi soruluyor mu?`,
  reasonSameCuisine: (cuisine: string, importance: number) =>
    importance >= 80
      ? `${cuisine} menülerinde neredeyse her zaman var`
      : importance >= 60
        ? `${cuisine} menülerinde sık görülür`
        : `${cuisine} menülerinde görülür`,
  reasonRelatedCuisine: (related: string) => `${related} ürünü; menüyü genişletir`,
  progressExtract: 'Panel ekran görüntüleri okunuyor',
  progressAnalyze: 'Menü karşılaştırılıyor',
  progressRecommend: 'Ek öneriler hazırlanıyor',
  extractFailed: (kind: string) => `Bir ekran görüntüsü okunamadı (${kind}).`,
  aiUnavailable: 'AI kapalı veya kota dolu: yalnızca önbellekteki ekran görüntüleri ve kayıtlı şube menüsü kullanıldı.',
  noItems: 'Ekran görüntülerinde ürün bulunamadı; ürün listesinin göründüğü ekranı paylaş.',
  aiRecommendationsFailed: 'Ek AI önerileri alınamadı; veritabanı önerileri gösteriliyor.',
  providerFallback: (failed: string) => `Birincil sağlayıcı yanıt vermedi (${failed}); yedek kullanıldı.`,
} as const;
